(()=>{
  // Product IDs are generated by admin.js. This file only enforces the read-only UI.
  const lockProductId=()=>{
    const input=document.getElementById('productId');
    if(!input)return;
    input.readOnly=true;
    input.tabIndex=-1;
    input.setAttribute('aria-readonly','true');
    input.title='Product ID is generated automatically and cannot be changed.';
  };
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',lockProductId);else lockProductId();
})();
